import { useEffect, useReducer } from "react";
import { getComments } from "./api";

const STATUS = {
  error: "error",
  loading: "loading",
  ready: "ready",
};

const ACTION = {
  error: "error",
  loading: "loading",
  success: "success",
};

function createState(overrides = {}) {
  return {
    comments: [],
    error: null,
    status: STATUS.loading,
    ...overrides,
  };
}

function commentsReducer(state, action) {
  switch (action.type) {
    case ACTION.loading:
      return createState();
    case ACTION.success:
      return createState({
        comments: action.comments,
        status: STATUS.ready,
      });
    case ACTION.error:
      return createState({
        comments: [],
        error: action.error,
        status: STATUS.error,
      });
    default:
      return state;
  }
}

export function useComments(slug) {
  const [state, dispatch] = useReducer(commentsReducer, undefined, createState);

  useEffect(() => {
    const controller = new AbortController();

    dispatch({ type: ACTION.loading });

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        dispatch({ type: ACTION.success, comments });
      })
      .catch((err) => {
        if (err?.name === "AbortError") {
          return;
        }

        dispatch({ type: ACTION.error, error: err.message });
      });

    return () => {
      controller.abort();
    };
  }, [slug]);

  return {
    comments: state.comments,
    error: state.error,
    isLoading: state.status === STATUS.loading,
  };
}

